sys_script_client.script:
function onSubmit() {
    // Standardize values by trimming whitespace
    var rewardType = String(g_form.getValue('reward_type'));
    var leavesDay = String(g_form.getValue('leaves_day')).trim();
        g_form.addErrorMessage(rewardType);

    // Check conditions strictly
    // if (rewardType === 'extra_leave_credit' && (leavesDay === '0' || leavesDay === '')) 
    if (rewardType == 'extra_leave_credit') {
        g_form.addErrorMessage('leaves days cannot be empty');

        // Force focus back to the field to help the user
        g_form.getControl('leaves_day').focus();

        return false; // Strictly aborts the submission
    }
}
